# 13-nov-2026 · Extra sections appended to the shorter existing guides (English source, translated at build time).
# Same rules: no hotel names, no invented prices, no em dashes, only facts we can stand behind.
def PL(s, t): return f'<a href="/{{l}}/place/{s}/">{t}</a>'
def GD(s, t): return f'<a href="/{{l}}/guide/{s}/">{t}</a>'
MAP = '<a href="/{l}/map/">interactive map</a>'
ADD = {}
FAQ = {}

ADD["pasola-guide"] = f"""<h2>Where the Pasola takes place</h2><p>The Pasola is held in West and Southwest Sumba, in the traditional districts of Kodi, Lamboya, Wanokaka and Gaura. Each community holds its own Pasola on its own field, often near the coast, so there are several events spread over February and March. The best known fields include the one at {PL('pasola-wanokaka', 'Wanokaka')} and those near {PL('wainyapu', 'Wainyapu')} in Kodi.</p>
<h2>Why the dates move</h2><p>The exact day is set by local priests following the ritual calendar, which is linked to the moon and to the arrival of sea worms called nyale on the beaches. Before the contest, priests go to the shore at dawn to read the worms as a sign for the coming harvest. That is why dates are confirmed late and can change. For the latest schedule see {GD('pasola-dates', 'Pasola dates')}.</p>
<h2>What you will see</h2><p>Two groups of riders face each other and charge, throwing blunt wooden spears while riding bareback or with simple saddles. The atmosphere is intense and crowded, with families watching from the edges of the field. Injuries can happen, and in the tradition blood spilled on the ground is linked to fertility of the land.</p>
<h2>Practical tips for spectators</h2><ul><li>Fly into {GD('tambolaka-airport', 'Tambolaka')}, the closest airport, and stay in Tambolaka, Waikabubak or near the coast.</li><li>Go with a local guide who can confirm the day and the time, which often changes.</li><li>Arrive early, stay behind the crowd and never walk onto the field.</li><li>Ask before photographing people and rituals, and avoid flying drones over riders and horses.</li><li>Bring water, a hat and cash; there are few facilities.</li></ul>"""
FAQ["pasola-guide"] = [["Is the Pasola dangerous for spectators?", "It can be if you stand too close. Horses and spears move fast, so stay behind the crowd and follow local instructions."], ["Where is the Pasola held?", "In West and Southwest Sumba, in Kodi, Lamboya, Wanokaka and Gaura, on several dates in February and March."]]

ADD["surf-sumba"] = f"""<h2>The main surf areas</h2><p>Sumba's surf faces the Indian Ocean on the south and west coasts. The best known breaks include the world-famous left at Nihiwatu, which is private and reserved for guests of the resort there, and public spots along the coasts of Lamboya, Kodi and East Sumba. On our map you can find {PL('marosi-beach', 'Marosi')}, {PL('pero-beach', 'Pero')}, {PL('tarimbang-bay', 'Tarimbang')} and {PL('rua-beach', 'Rua')}, all known for waves.</p>
<h2>Season</h2><p>The most consistent swells come in the dry season, roughly April to October, when Southern Hemisphere storms send long-period swells and the trade winds blow offshore on many south-facing breaks in the morning. The wet season brings smaller, messier surf and more onshore wind, but also emptier lineups.</p>
<h2>Level and safety</h2><ul><li>Many breaks are over reef and are suitable for intermediate and advanced surfers only.</li><li>There are no lifeguards; never surf alone and ask locals about currents.</li><li>Bring a first-aid kit for reef cuts, reef booties and spare leashes and wax: surf shops are rare.</li><li>Respect local surfers and fishermen; some beaches are used for boats and ceremonies.</li></ul>
<h2>Getting there with a board</h2><p>Flights to Sumba use small planes and boards may cost extra or need to be booked in advance. Check your airline's rules before flying. See {GD('tambolaka-airport', 'Tambolaka Airport')} and {GD('waingapu-airport', 'Waingapu Airport')}.</p>"""

ADD["ikat-guide"] = f"""<h2>How Sumba ikat is made</h2><p>Ikat means that the threads are tied and dyed before weaving. Bundles of cotton thread are stretched on a frame, sections are tightly bound so they resist the dye, and the threads are dipped, untied and re-tied for each colour. Traditional dyes come from plants: indigo for blue and the roots of the morinda tree for deep red. A large cloth can take months to complete.</p>
<h2>Symbols</h2><p>Motifs tell stories and show status: horses, roosters, crocodiles, shrimp, skulls on trees in old cloths, and figures of ancestors. East Sumba is especially famous for large hinggi cloths worn by men and the lau skirts worn by women.</p>
<h2>Where to see weaving</h2><ul><li>{PL('prailiu-village', 'Prailiu')} near Waingapu, with many weavers.</li><li>{PL('praiyawang-rende', 'Praiyawang (Rende)')} in East Sumba, a royal village known for fine cloths.</li><li>Villages in West Sumba such as {PL('prai-ijing', 'Prai Ijing')}.</li></ul>
<h2>Buying fairly</h2><ul><li>Buy directly from weavers when possible and ask who made the cloth.</li><li>Natural dyes and hand-spun thread take far longer and are worth more than synthetic dyes.</li><li>Bargaining is normal but be fair: a good cloth represents weeks of work.</li></ul>"""

ADD["budget-guide"] = f"""<h2>What you will spend money on</h2><ul><li><b>Flights:</b> usually the biggest single cost; prices change with season and how early you book. See {GD('tambolaka-airport', 'Tambolaka')}.</li><li><b>Car with driver:</b> the main daily cost; agree what is included (fuel, meals, parking). See {GD('hire-a-driver-sumba', 'hiring a driver')}.</li><li><b>Accommodation:</b> from simple guesthouses in town to a few high-end resorts.</li><li><b>Food:</b> local warungs are inexpensive; imported food and drinks cost more.</li><li><b>Entry, parking and village contributions:</b> small amounts, in cash.</li></ul>
<h2>How to keep costs down</h2><ul><li>Share a car and driver with other travellers.</li><li>Fly into one airport and out of the other to avoid a long drive back.</li><li>Stay in towns such as Waikabubak or Waingapu and do day trips.</li><li>Eat at local warungs.</li><li>Travel in May, June or September rather than July and August for easier bookings.</li></ul>
<h2>Cash</h2><p>Most expenses are paid in cash. Read {GD('money-atms-sim-sumba', 'money, ATMs and SIM cards')} before you go.</p>"""

ADD["health-safety"] = f"""<h2>Before you travel</h2><ul><li>Visit a travel clinic about six weeks before departure for vaccines and advice on malaria prevention.</li><li>Buy travel insurance that covers medical evacuation; serious cases are flown to Bali or beyond.</li><li>Pack a first-aid kit and enough of your own medicines.</li></ul>
<h2>Mosquitoes</h2><p>Malaria and dengue are present in parts of East Nusa Tenggara. Use repellent, wear long sleeves at dusk and sleep under a net where provided. See a doctor quickly if you develop a fever during or after the trip, and mention that you were in Sumba.</p>
<h2>Water and food</h2><p>Drink only bottled, boiled or filtered water. Choose busy warungs with freshly cooked food. Carry oral rehydration salts.</p>
<h2>Sun and heat</h2><p>At 10 degrees south the sun is strong all year, especially in East Sumba. Wear a hat, use sunscreen and drink plenty of water on hikes such as {PL('tanggedu-waterfall', 'Tanggedu')}.</p>
<h2>The sea and the roads</h2><p>The biggest dangers are rip currents on exposed beaches and driving at night. Read {GD('is-sumba-safe', 'is Sumba safe?')} for practical advice.</p>"""

ADD["sumba-vs-bali"] = f"""<h2>Side by side</h2><ul><li><b>Getting there:</b> Bali has direct international flights; Sumba is about an hour's flight from Bali.</li><li><b>Crowds:</b> Bali is one of Asia's busiest destinations; Sumba is still quiet.</li><li><b>Culture:</b> Bali's Hindu temples and ceremonies; Sumba's Marapu villages, megalithic tombs and the Pasola.</li><li><b>Beaches:</b> Bali has many developed beaches; Sumba has wild, empty ones such as {PL('mandorak-beach', 'Mandorak')} and {PL('tarimbang-bay', 'Tarimbang')}.</li><li><b>Services:</b> Bali has everything; Sumba has the basics, mainly in towns.</li></ul>
<h2>Combining both</h2><p>Many travellers spend a few days in Bali and then fly to Sumba. A good plan is to keep a night in Bali before your international flight home, in case of delays. See {GD('bali-to-sumba', 'Bali to Sumba')}.</p>"""

ADD["best-time-weather"] = f"""<h2>Season by season</h2><p><b>Dry season (about May to October):</b> clear skies, golden savanna, easy roads; the best time for most trips. July to September are the driest months and have cool nights in the highlands.</p><p><b>Wet season (about November to April):</b> green landscapes, full waterfalls and fewer visitors, but heavy showers and muddy tracks. February and March are Pasola months.</p><p>The east is much drier than the west, and the highlands around Waikabubak are the coolest and wettest. Full month-by-month tables are in {GD('sumba-weather-by-month', 'Sumba weather by month')}, and live forecasts on our <a href="/{{l}}/weather/">weather page</a>.</p>"""

ADD["getting-there-around"] = f"""<h2>Which airport?</h2><p>Sumba has two airports: {GD('tambolaka-airport', 'Tambolaka (TMC)')} in the west and {GD('waingapu-airport', 'Waingapu (WGP)')} in the east. Fly into one and out of the other to see the whole island without backtracking.</p><h2>By boat</h2><p>Ships connect Waingapu and Waikelo with Flores, Sumbawa and Timor. The Sape to Waikelo ferry reopened in May 2026. See {GD('ferry-to-sumba', 'ferry to Sumba')}.</p><h2>On the island</h2><p>Public transport is limited, so most visitors hire a car with a driver. See {GD('hire-a-driver-sumba', 'hiring a driver')} and {GD('getting-around-sumba', 'getting around Sumba')}.</p>"""

ADD["respect-etiquette"] = f"""<h2>Before entering a village</h2><ul><li>Stop at the entrance and wait to be welcomed; a guide or driver can introduce you.</li><li>Sign the guestbook and leave a contribution.</li><li>Ask before photographing people, houses and tombs.</li></ul><h2>Inside a house</h2><ul><li>Enter only if invited, and take off your shoes if your hosts do.</li><li>Some parts of the house are reserved; follow your host.</li><li>If you are offered betel nut (sirih pinang), you can politely decline.</li></ul><h2>Tombs and sacred places</h2><p>Never sit or climb on stone tombs, and do not touch ritual objects. Read about {GD('marapu-religion-sumba', 'Marapu')} and {GD('sumba-megalithic-tombs', 'megalithic tombs')} to understand why.</p>"""

ADD["food-in-sumba"] = f"""<h2>What to expect</h2><p>Food in Sumba is simple and filling: rice with vegetables, fish, chicken, eggs and noodles, often with sambal (chilli sauce). In towns you will find warungs, small markets and a few cafés. In the countryside, choices are limited, so pack snacks and water for long drives.</p><h2>Tips</h2><ul><li>Ask for "tidak pedas" if you do not want chilli.</li><li>Fresh fish is best near the coast, especially in fishing villages.</li><li>Markets in Waingapu and Waikabubak sell tropical fruit.</li><li>Drink bottled or filtered water.</li><li>Ceremonies may involve meat from sacrificed animals; you can politely decline food.</li></ul>"""

ADD["east-vs-west-sumba"] = f"""<h2>West and Southwest Sumba</h2><p>Greener and wetter, with the famous Kodi coast ({PL('weekuri-lagoon', 'Weekuri')}, {PL('mandorak-beach', 'Mandorak')}, {PL('ratenggaro', 'Ratenggaro')}), the highland town of Waikabubak, many traditional villages and the Pasola in February and March. Gateway: {GD('tambolaka-airport', 'Tambolaka')}.</p><h2>East Sumba</h2><p>Drier and more open, with savanna hills like {PL('wairinding-hill', 'Wairinding')}, the canyon of {PL('tanggedu-waterfall', 'Tanggedu')}, the sunsets of {PL('walakiri-beach', 'Walakiri')} and ikat villages such as {PL('prailiu-village', 'Prailiu')}. Gateway: {GD('waingapu-airport', 'Waingapu')}.</p><h2>Central Sumba</h2><p>Between the two, Central Sumba has the megalithic tombs of Anakalang and the quiet north coast at Mamboro. See {GD('sumba-north-coast', 'the north coast')}.</p>"""

ADD["is-sumba-worth-it"] = f"""<h2>Who will love Sumba</h2><ul><li>Travellers who want empty landscapes and beaches.</li><li>People curious about living traditions.</li><li>Surfers and photographers.</li><li>Anyone happy with simple comfort and long drives.</li></ul><h2>Who may not</h2><ul><li>Those looking for nightlife, shopping or many restaurants.</li><li>Travellers with only two or three days and no flexibility.</li><li>People who need fast medical care nearby.</li></ul><p>If you are unsure, compare with {GD('sumba-vs-bali', 'Bali')}, {GD('sumba-vs-lombok', 'Lombok')} and {GD('sumba-vs-flores', 'Flores')}.</p>"""

ADD["sumba-north-coast"] = f"""<h2>Why the north coast</h2><p>The north coast of Central and East Sumba is calmer than the south: the sea is often gentler, beaches are quiet and the savanna runs down to the shore. Around Mamboro you will find {PL('kapulit-beach', 'Kapulit')}, {PL('mananga-beach', 'Mananga')}, {PL('karendi-beach', 'Karendi')} and the {PL('mamboro-savanna', 'Mamboro savanna')}.</p><h2>Getting there</h2><p>The coast road links Tambolaka and Waingapu. It is a good alternative to the inland route when crossing the island, with stops at beaches along the way. See the {MAP}.</p>"""

ADD["where-to-stay-in-sumba"] = f"""<h2>Choosing a base</h2><ul><li><b>Tambolaka:</b> closest to the airport and the Kodi coast; practical for a first night.</li><li><b>Kodi coast:</b> beaches and villages on your doorstep, few services.</li><li><b>Waikabubak:</b> cool highland town in the middle of the traditional villages of West Sumba.</li><li><b>Central Sumba and Mamboro:</b> quiet, between west and east.</li><li><b>Waingapu:</b> the biggest town, base for East Sumba.</li><li><b>South coast:</b> remote surf beaches; plan an overnight.</li></ul><p>We do not list or rank hotels. Choose by location using our {MAP}, which shows drive times from each town.</p>"""

ADD["getting-around-sumba"] = f"""<h2>Distances</h2><p>Sumba is about 200 km from west to east. Driving from Tambolaka to Waingapu takes most of a day. Plan your trip region by region, and use two airports if possible.</p><h2>Options</h2><ul><li><b>Car with driver:</b> the most common and comfortable choice; see {GD('hire-a-driver-sumba', 'hiring a driver')}.</li><li><b>Scooter:</b> for experienced riders only.</li><li><b>Public buses (bemo) and shared cars:</b> run between towns, not to most sights.</li></ul><h2>Road tips</h2><ul><li>Avoid driving after dark.</li><li>Fuel up in towns.</li><li>Expect animals on the road.</li><li>In the wet season, ask about road conditions each day.</li></ul>"""

ADD["bali-to-sumba"] = f"""<h2>Flight or ferry?</h2><p>The flight from Bali takes about an hour; there are several flights a day to {GD('tambolaka-airport', 'Tambolaka')} and regular flights to {GD('waingapu-airport', 'Waingapu')}. Ships from Bali exist but take much longer and are infrequent; see {GD('ferry-to-sumba', 'ferry to Sumba')}.</p><h2>Tips</h2><ul><li>Book morning flights when you can.</li><li>Check baggage rules on small planes.</li><li>Leave a buffer before international connections in Bali.</li></ul>"""

ADD["sumba-waterfalls"] = f"""<h2>When to go</h2><p>Waterfalls are fullest in and just after the wet season, roughly December to April, and thinnest in September and October. In the dry season the water is clearer and paths are easier.</p><h2>Safety</h2><ul><li>Rocks are slippery: wear sandals with grip.</li><li>Do not swim after heavy rain, when water can rise quickly.</li><li>Some falls require a walk or a river crossing; ask locally.</li></ul>"""

ADD["marapu-religion-sumba"] = f"""<h2>Marapu in daily life</h2><p>Marapu shapes the layout of villages, the form of the houses, the stone tombs and the calendar of rituals, including the Pasola. Many Sumbanese are Christian and also follow Marapu customs. See {GD('sumba-traditional-houses', 'traditional houses')}, {GD('sumba-megalithic-tombs', 'megalithic tombs')} and {GD('sumba-horses', 'horses in Sumba')}.</p><h2>As a visitor</h2><p>Be respectful at ceremonies, ask before taking photos and follow your guide. Read {GD('respect-etiquette', 'village etiquette')}.</p>"""

ADD["sumba-practical-tips"] = f"""<h2>Quick checklist</h2><ul><li>Cash in small notes: {GD('money-atms-sim-sumba', 'money and ATMs')}.</li><li>SIM card or eSIM before arrival.</li><li>A driver arranged in advance: {GD('hire-a-driver-sumba', 'hiring a driver')}.</li><li>Travel insurance with evacuation.</li><li>Packing list: {GD('sumba-packing-list', 'what to bring')}.</li><li>Time zone: WITA, UTC+8, same as Bali.</li><li>Plugs: type C and F, 230 V.</li></ul>"""

for k, t in [("itinerary-3-days", "3"), ("itinerary-5-days", "5"), ("itinerary-7-days", "7")]:
    ADD[k] = f"""<h2>Tips for this route</h2><ul><li>Start early each day: light is best and roads are quieter.</li><li>Keep afternoons flexible for rain in the wet season.</li><li>Agree the route with your driver the day before; see {GD('hire-a-driver-sumba', 'hiring a driver')}.</li><li>Want more time? See the {GD('itinerary-10-days', '10-day itinerary')}.</li></ul>"""

ADD["sumba-travel-guide"] = f"""<h2>Sumba by numbers</h2><ul><li><b>4 regencies:</b> Southwest Sumba, West Sumba, Central Sumba and East Sumba.</li><li><b>2 airports:</b> {GD('tambolaka-airport', 'Tambolaka (TMC)')} and {GD('waingapu-airport', 'Waingapu (WGP)')}, each about an hour from Bali.</li><li><b>About 200 km</b> from west to east; plan most of a day to drive across.</li><li><b>2 seasons:</b> dry from about May to October, wet from about November to April.</li><li><b>Time zone:</b> WITA, UTC+8, the same as Bali.</li><li><b>41 places</b> checked on our {MAP}, each with photos, drive times and practical tips.</li></ul>
<h2>Planning your days</h2><p>The most common mistake is underestimating distances. Two or three main stops a day is a good pace. If you have three days, stay in the west. With five days, add the east by flying out of the other airport. With a week or more, add Central Sumba and a remote coast. Our itineraries are ready to use: {GD('itinerary-3-days', '3 days')}, {GD('itinerary-5-days', '5 days')}, {GD('itinerary-7-days', '7 days')} and {GD('itinerary-10-days', '10 days')}.</p>
<h2>Weather and when to go, in detail</h2><p>The east is one of the driest areas of Indonesia, while the highlands around Waikabubak receive several times more rain. July to September are the driest months almost everywhere; January to March are the wettest. Daytime temperatures on the coast are around 29 to 32 °C all year, and nights in the highlands can be fresh in July and August. See {GD('sumba-weather-by-month', 'Sumba weather by month')} for tables with ten years of data, and {GD('sumba-in-the-rainy-season', 'Sumba in the rainy season')} if you are travelling between November and April.</p>
<h2>Arriving: airports and ferries</h2><p>Most visitors fly from Bali. Tambolaka has the most flights and serves the west; Waingapu serves the east. Some travellers arrive by sea from Flores, Sumbawa or Timor: the ferry from Sape (Sumbawa) to Waikelo near Tambolaka was reopened in May 2026, and ships run between Ende (Flores) and Waingapu. See {GD('ferry-to-sumba', 'ferry to Sumba')}.</p>
<h2>Getting around</h2><p>There is very little public transport to the sights, so most people hire a car with a local driver, who also helps in villages. Experienced riders can use a scooter, but roads are narrow and dark at night. Read {GD('hire-a-driver-sumba', 'hiring a driver')} and {GD('getting-around-sumba', 'getting around')}.</p>
<h2>Money, phone and internet</h2><p>Cash is essential outside the towns; ATMs are in Waingapu, Waikabubak, Tambolaka and Waibakul. Telkomsel generally has the widest mobile coverage, but signal disappears on remote coasts. See {GD('money-atms-sim-sumba', 'money, ATMs and SIM cards')}.</p>
<h2>Health and safety</h2><p>Sumba is generally calm and friendly. The main risks are road travel, strong currents on exposed beaches and limited healthcare, so travel insurance with medical evacuation is essential. Protect yourself from mosquitoes and drink safe water. Read {GD('is-sumba-safe', 'is Sumba safe?')} and {GD('health-safety', 'health and safety')}.</p>
<h2>Culture and respect</h2><p>Sumba's traditional villages are homes, not open-air museums. Greet people, sign the guestbook, leave a contribution, dress modestly and ask before taking photos. Learn about {GD('marapu-religion-sumba', 'Marapu')}, {GD('sumba-traditional-houses', 'the tall thatched houses')}, {GD('sumba-megalithic-tombs', 'megalithic tombs')}, {GD('ikat-guide', 'ikat weaving')} and {GD('sumba-horses', 'Sumba horses')} to understand what you see.</p>
<h2>Events</h2><p>The Pasola, a ritual contest on horseback, takes place in February and March in West and Southwest Sumba. Dates are set by local tradition and confirmed late; see {GD('pasola-dates', 'Pasola dates')}.</p>
<h2>What to pack</h2><p>Sun protection, insect repellent, modest clothes for villages, sandals with grip, a light jacket for the highlands, a headlamp, a power bank and cash. The full list is in {GD('sumba-packing-list', 'our Sumba packing list')}.</p>
<h2>Sumba compared</h2><p>Not sure if Sumba is for you? Read our honest comparisons with {GD('sumba-vs-bali', 'Bali')}, {GD('sumba-vs-lombok', 'Lombok')} and {GD('sumba-vs-flores', 'Flores')}, and {GD('is-sumba-worth-it', 'is Sumba worth it?')}.</p>
<h2>All places in one list</h2><p>For a complete overview by region, see {GD('places-to-visit-in-sumba', 'places to visit in Sumba')}, or explore the {MAP}, where you can filter by beaches, waterfalls, villages, viewpoints and culture, save places and turn them into a route.</p>"""
FAQ["sumba-travel-guide"] = [["Which airport is best for Sumba?", "Tambolaka for the west (Weekuri, Kodi, Waikabubak) and Waingapu for the east (Wairinding, Walakiri, Tanggedu). For a full trip, fly into one and out of the other."], ["Can I get to Sumba by ferry?", "Yes, from Flores (Ende to Waingapu, about 13 hours), Sumbawa (Sape to Waikelo, about 8 to 9 hours) and Timor, but ships are not daily."], ["Do I need cash in Sumba?", "Yes. Outside the towns almost everything is paid in cash, so withdraw at ATMs in Waingapu, Waikabubak, Tambolaka or Waibakul."]]

ADD["things-to-do-in-sumba"] = f"""<h2>More things to do</h2><ul><li>Watch the Pasola in February or March: {GD('pasola-dates', 'dates')}.</li><li>Learn how ikat is woven at {PL('prailiu-village', 'Prailiu')}: {GD('ikat-guide', 'ikat guide')}.</li><li>Catch the sunset at {PL('walakiri-beach', 'Walakiri')}: {GD('best-sunsets-in-sumba', 'best sunsets')}.</li><li>See the megalithic tombs of Anakalang: {GD('sumba-megalithic-tombs', 'tombs')}.</li><li>Surf the south coast: {GD('surf-sumba', 'surf guide')}.</li><li>Explore the quiet {GD('sumba-north-coast', 'north coast')} around Mamboro.</li><li>Plan your route with the {MAP} and save your favourite places.</li></ul>"""
ADD["best-beaches-in-sumba"] = f"""<h2>Choosing a beach</h2><p>Sumba's south and west coasts face the open Indian Ocean, with big waves and strong currents for much of the year: spectacular, but not always safe for swimming. The north coast around Mamboro is usually calmer. For safe swimming, {PL('weekuri-lagoon', 'Weekuri Lagoon')} is the classic choice. Always check conditions locally and never swim alone.</p><h2>Best for</h2><ul><li><b>Sunset:</b> {PL('walakiri-beach', 'Walakiri')}, {PL('pero-beach', 'Pero')}; see {GD('best-sunsets-in-sumba', 'best sunsets')}.</li><li><b>Surf:</b> {PL('marosi-beach', 'Marosi')}, {PL('tarimbang-bay', 'Tarimbang')}; see {GD('surf-sumba', 'surf guide')}.</li><li><b>Solitude:</b> the north coast, such as {PL('kapulit-beach', 'Kapulit')} and {PL('mananga-beach', 'Mananga')}.</li><li><b>Cliffs and views:</b> {PL('mandorak-beach', 'Mandorak')} and {PL('watu-maladong', 'Watu Maladong')}.</li></ul>"""
ADD["traditional-villages-sumba"] = f"""<h2>Visiting well</h2><p>Go with a local guide or driver who can introduce you, sign the guestbook and leave a contribution, dress modestly, and ask before photos. Never climb on the tombs. Read {GD('respect-etiquette', 'village etiquette')}, {GD('sumba-traditional-houses', 'traditional houses')} and {GD('sumba-megalithic-tombs', 'megalithic tombs')} first.</p>"""

# 21-nov-2026: the full list of 50 things, built from the map data (one line per place from its own text)
def _fifty():
    from places import PLACES as _P
    from places_mamboro import MAMBORO as _MB
    import re as _re
    order = {"beach": 0, "waterfall": 1, "village": 2, "viewpoint": 3, "culture": 4}
    _seen = set(); _u = [p for p in _P + _MB if not (p["s"] in _seen or _seen.add(p["s"]))]
    items = sorted(_u, key=lambda p: (order.get(p["c"], 9), p["en"]["n"]))
    lines = []
    for p in items:
        first = _re.split(r"(?<=[.!?])\s", p["en"]["t"].strip())[0]
        lines.append(f"<li>{PL(p['s'], p['en']['n'])}: {first}</li>")
    extra = [
        f"See a Pasola, the ritual horseback spear contest of February and March ({GD('pasola-dates', 'dates')}).",
        f"Watch ikat being tied, dyed and woven in an East Sumba village ({GD('sumba-ikat-weaving', 'ikat guide')}).",
        f"Walk the savannah ridges at sunrise ({GD('hiking-sumba', 'hiking guide')}).",
        f"Go to a town market early in the morning ({GD('sumba-markets', 'markets')}).",
        f"Watch Sumba's sandalwood ponies on the beaches and hills ({GD('sumba-horses', 'horses of Sumba')}).",
        f"Surf the reef breaks of the south and west coasts ({GD('surf-sumba', 'surf guide')}).",
        f"Snorkel the reefs on a calm morning ({GD('snorkeling-diving-sumba', 'snorkelling and diving')}).",
        f"Eat in a local warung ({GD('food-in-sumba', 'food in Sumba')}).",
        f"Learn ten words of Indonesian before you go ({GD('indonesian-phrases-sumba', 'phrases')}).",
    ]
    lines += [f"<li>{x}</li>" for x in extra]
    n = len(lines)
    return f"<h2>The full list: {n} things to do in Sumba</h2><p>Every place on our map, grouped by type, plus the experiences that are not tied to one spot. Each line links to the full page with directions, photos and the best time to go.</p><ol>{''.join(lines)}</ol>"
ADD["things-to-do-in-sumba"] = ADD.get("things-to-do-in-sumba", "") + _fifty()
